package io.github.devpanel.support;

import org.springframework.context.annotation.Condition;
import org.springframework.context.annotation.ConditionContext;
import org.springframework.core.type.AnnotatedTypeMetadata;
import org.springframework.util.ClassUtils;

/**
 * The starter carries the panel three times: this copy for Spring Boot 2.7 ({@code javax.servlet})
 * and, generated by the build from the same sources, copies in {@code io.github.devpanel.boot3}
 * (Spring Boot 3, {@code jakarta.servlet}) and {@code io.github.devpanel.boot4} (Spring Boot 4,
 * Jackson 3). Each entry point (auto-configuration, environment post-processor, initializer, test
 * listener) asks this class whether its copy is the one for the running application; the other
 * copies are never loaded.
 *
 * <p>Decided by the Spring Framework generation (6 has {@code org.springframework.aot}, 7 has
 * {@code org.springframework.core.retry}), not by which servlet API happens to be on the
 * classpath: old libraries drag {@code javax.servlet} into Boot 3 applications and the other way
 * round.
 */
public final class DevPanelFlavor implements Condition {

  /** The Spring Framework generation this copy is for; the build sets 6 and 7 in the others. */
  public static final int SPRING = 5;

  private static final String SPRING_6_MARKER = "org.springframework.aot.AotDetector";
  private static final String SPRING_7_MARKER = "org.springframework.core.retry.RetryTemplate";

  public static boolean active(ClassLoader classLoader) {
    ClassLoader loader = classLoader != null ? classLoader : DevPanelFlavor.class.getClassLoader();
    int running = ClassUtils.isPresent(SPRING_7_MARKER, loader) ? 7
        : ClassUtils.isPresent(SPRING_6_MARKER, loader) ? 6 : 5;
    return running == SPRING;
  }

  @Override
  public boolean matches(ConditionContext context, AnnotatedTypeMetadata metadata) {
    return active(context.getClassLoader());
  }
}
